import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { color, vec3, positionLocal, mix, uv } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  const root = new Group();

  // Color System
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- STAGE BACKDROP / BASE PANEL ---
  // Large stage background at z = -2.5 to avoid FLAT_VOID
  const bgGeom = new PlaneGeometry(8, 7);
  const bgMat = new MeshBasicNodeMaterial();

  // Vertical gradient shader using TSL
  const uvs = uv();
  const gradMix = mix(
    color(colors.surface),
    color(colors.ink),
    uvs.y
  );
  bgMat.colorNode = gradMix;

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  root.add(bgMesh);

  // Compact card plate (Machined Surface)
  const cardWidth = 3.2;
  const cardHeight = 2.0;
  const cardGeom = new PlaneGeometry(cardWidth, cardHeight);
  const cardMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    roughness: 0.25,
    metalness: 0.9,
    roughnessMap: null,
    metalnessMap: null,
    transparent: true,
    opacity: 0.95
  });
  const cardMesh = new Mesh(cardGeom, cardMat);
  cardMesh.position.set(0, 0, -0.1);
  root.add(cardMesh);

  // --- HERO SUBJECT: GEAR MESH ---
  const gearGroup = new Group();
  gearGroup.position.set(-0.8, 0, 0.1);
  gearGroup.scale.set(0.65, 0.65, 0.65);
  root.add(gearGroup);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      gltf.scene.traverse((child) => {
        if (child.isMesh) {
          // Apply machined metal PBR
          child.material = new MeshStandardNodeMaterial({
            color: colors.paper,
            roughness: 0.3,
            metalness: 0.85,
            flatShading: false
          });
        }
      });
      gearGroup.add(gltf.scene);

      // Idle rotation
      gsap.to(gearGroup.rotation, {
        z: Math.PI * 2,
        duration: 12,
        repeat: -1,
        ease: 'none'
      });
    }).catch(err => console.warn('Failed to load mesh, fallback used', err));
  }

  // --- LOCAL LIGHTS (Rim + Key Accent) ---
  const localKeyLight = new DirectionalLight(colors.paper, 1.2);
  localKeyLight.position.set(2, 2, 3);
  root.add(localKeyLight);

  const localAccentLight = new DirectionalLight(colors.accent, 1.5);
  localAccentLight.position.set(-3, -2, 1);
  root.add(localAccentLight);

  const localAmbient = new AmbientLight(colors.surface, 0.4);
  root.add(localAmbient);

  // --- TEXT INTERACTION & LABELS ---
  const textGroup = new Group();
  textGroup.position.set(0.6, 0, 0.1);
  root.add(textGroup);

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  if (textItems.length >= 2) {
    const valText = ctx.fontAtlas.createText(textItems[0].text, {
      fontSize: 0.35,
      color: colors.paper,
      align: 'left'
    });
    valText.position.set(0, 0.2, 0);
    textGroup.add(valText);

    const labelText = ctx.fontAtlas.createText(textItems[1].text.toUpperCase(), {
      fontSize: 0.12,
      color: colors.accent,
      align: 'left',
      letterSpacingPx: 8
    });
    labelText.position.set(0, -0.2, 0);
    textGroup.add(labelText);
  } else {
    // Default fallback labels if none provided to ensure look-and-feel match
    const valText = ctx.fontAtlas.createText("98%", {
      fontSize: 0.45,
      color: colors.paper,
      align: 'left'
    });
    valText.position.set(0, 0.15, 0);
    textGroup.add(valText);

    const labelText = ctx.fontAtlas.createText("CHRONO PERFORMANCE", {
      fontSize: 0.1,
      color: colors.accent,
      align: 'left',
      letterSpacingPx: 6
    });
    labelText.position.set(0, -0.25, 0);
    textGroup.add(labelText);
  }

  // --- ENTRANCE ANIMATION (Weighted Settle) ---
  root.position.y += 0.4;
  root.scale.set(0.9, 0.9, 0.9);

  const entranceTl = gsap.timeline();
  entranceTl.to(root.position, {
    y: config.scenePosition?.[1] ?? -0.2,
    duration: 0.9,
    ease: 'power4.out'
  });
  entranceTl.to(root.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out'
  }, '<');

  // --- IN-SCENE INTERACTION EVENT HANDLERS ---
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: (config.scenePosition?.[1] ?? -0.2) + 0.15,
    duration: 0.3,
    ease: 'power2.out'
  });

  root.userData.handlers = {
    pointerover: () => {
      hoverTimeline.play();
    },
    pointerout: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      ctx.emit('hub-collection.select', { id: config.id });
    }
  };

  // --- CINEMATIC PRIMITIVES ---
  const appliedPrimitives = [];
  if (config.cinematicPrimitives) {
    for (const primitive of config.cinematicPrimitives) {
      if (ctx.primitives[primitive.name]) {
        const primRes = ctx.primitives[primitive.name](root, primitive.params);
        if (primRes) appliedPrimitives.push(primRes);
      }
    }
  }

  // --- CLEANUP ---
  root.userData.cleanup = () => {
    entranceTl.kill();
    hoverTimeline.kill();
    appliedPrimitives.forEach(p => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });
    bgGeom.dispose();
    bgMat.dispose();
    cardGeom.dispose();
    cardMat.dispose();
  };

  return root;
}
